action.code:
// Check if the filesystem context is valid
if (lfs == nullptr) {
    return LFS_ERR_NOSPC;
}

// Check if the block pointer is valid
if (block == nullptr) {
    return LFS_ERR_NOSPC;
}

// Get the free block count from the filesystem context
int free_block_count = lfs->free_block_count;

// If there are no free blocks, return an error
if (free_block_count == 0) {
    return LFS_ERR_NOSPC;
}

// Calculate the block number using the lookahead buffer and wear leveling
lfs_block_t allocated_block = lfs->lookahead_buffer[lfs->lookahead_index % lfs->lookahead_size];
lfs->lookahead_index = (lfs->lookahead_index + 1) % lfs->lookahead_size;

// Update the free block count
lfs->free_block_count--;

// Store the allocated block number
*block = allocated_block;

// Return success
return 0;

